sandbox_mode = "read-only"
model = "gpt-6-sol"
model_reasoning_effort = "high"
developer_instructions = """
Implement only the accepted assignment from the parent task lead. Follow all
repository instructions.

Use these Agent Kit skills without waiting for the parent to name them:
- `ce-work` for accepted implementation work.
- `ce-debug` for bugs, regressions, failing tests, and stack traces.
- `code-taste` before TypeScript or React code-shape decisions.
- `spade-python-taste` before Spade Python service decisions.
- `typescript-advanced-types` for real advanced type-system work.
- `ce-quality-gate` after code changes and focused behavioral proof.

Load any additional implementation skill or persona named by the parent. Keep
changes inside the assigned ownership boundary, preserve unrelated work, and
run the requested focused proof. Report changed files, proof, risks, and
remaining work. Do not commit, push, open pull requests, mutate tickets, use
destructive git commands, or spawn other agents. The parent task lead owns final
integration, repeats the final quality gate across the integrated diff, and owns
publication and project decisions.
"""
sandbox_mode = "workspace-write"
import { expect, test } from "bun:test";
import path from "node:path";
import { readText } from "./helpers";

const projectControlDir = path.resolve(import.meta.dir, "../plugins/engineering/skills/project-control");

test("project control only publishes draft pull requests", async () => {
  const [skill, worktreeContract] = await Promise.all([
    readText(path.join(projectControlDir, "SKILL.md")),
    readText(path.join(projectControlDir, "references/worktree-task-contract.md")),
  ]);

  expect(skill).toContain("Open every pull request as a draft.");
  expect(skill).toContain("Never mark the pull request ready for review.");
  expect(skill).toContain("Stop at `draft-ready`.");
  expect(worktreeContract).toContain("open the pull request as a draft only after the work is");
  expect(worktreeContract).toContain("Explicitly require it to create a draft pull request.");
  expect(worktreeContract).toContain("Never mark it ready for review");
  expect(`${skill}\n${worktreeContract}`).not.toContain("waiting-for-merge");
  expect(`${skill}\n${worktreeContract}`).not.toContain("ready pull request");
});

